def unique_jobs(rows):
    """
    Deduplicate jobs by (source, source_id) - first occurrence wins.
    Rows with missing/None/empty source_id are kept separately.
    Does not merge across sources or by title. Does not mutate input.
    """
    seen = {}
    result = []
    for r in rows:
        source = r.get('source')
        source_id = r.get('source_id')
        # Handle missing/None/empty source_id - keep separately
        if source_id is None or source_id == '':
            key = (source, None)
            if key not in seen:
                seen[key] = True
                result.append(r)
        else:
            key = (source, source_id)
            if key not in seen:
                seen[key] = True
                result.append(r)
    return result
